from fastapi import APIRouter
from typing import List
from database import get_db
from schemas import RiskAlertSchema

router = APIRouter(prefix="/api/risks", tags=["Supply Chain Risks"])

@router.get("", response_model=List[RiskAlertSchema])
def list_risks():
    """Retrieve supply chain risk alerts generated by the Risk Agent."""
    with get_db() as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT * FROM risk_alerts ORDER BY CASE severity WHEN 'High' THEN 1 WHEN 'Medium' THEN 2 ELSE 3 END;")
        rows = cursor.fetchall()
    return rows
